{
  "rules": [
    {
      "rule_id": "KBYY-S2-R01-01",
      "source": {
        "quote": "만 19세 미만 실명의 개인"
      },
      "condition": {
        "<": [
          {
            "var": "customer.age"
          },
          19
        ]
      },
      "effect": {
        "type": "REQUIRE",
        "value": true,
        "unit": "age"
      }
    },
    {
      "rule_id": "KBYY-S2-R01-02",
      "source": {
        "quote": "개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
      },
      "condition": {
        "and": [
          {
            "==": [
              {
                "var": "customer.is_first_deposit"
              },
              false
            ]
          },
          {
            "or": [
              {
                "==": [
                  {
                    "var": "contract.channel"
                  },
                  "BRANCH"
                ]
              },
              {
                "==": [
                  {
                    "var": "contract.channel"
                  },
                  "ONLINE"
                ]
              }
            ]
          }
        ]
      },
      "effect": {
        "type": "DISQUALIFY",
        "value": true
      }
    },
    {
      "rule_id": "KBYY-S2-R01-03",
      "source": {
        "quote": "「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
      },
      "condition": {
        "and": [
          {
            "==": [
              {
                "var": "contract.channel"
              },
              "BRANCH"
            ]
          },
          {
            "exists": {
              "event": "PRODUCT_SWITCH",
              "within": {
                "ref": "$window"
              }
            }
          }
        ]
      },
      "effect": {
        "type": "DISQUALIFY",
        "value": true
      }
    }
  ]
}

